fn statAndPrint(writer: anytype, path: []const u8) !void {
    const file = std.fs.cwd().openFile(path, .{}) catch |err| {
        try writer.print("  stat: could not open ({s})\n", .{@errorName(err)});
        return;
    };
    defer file.close();

    const st = file.stat() catch |err| {
        try writer.print("  stat: could not stat ({s})\n", .{@errorName(err)});
        return;
    };

    const mtime_seconds = @divFloor(st.mtime, std.time.ns_per_s);
    try writer.print("  size: {d} bytes\n", .{st.size});
    try writer.print("  mtime: {d} (unix seconds)\n", .{mtime_seconds});
}

fn processPath(writer: anytype, path: []const u8) !void {
    const cat = detectCategory(path);
    const g = guidanceFor(cat);

    try writer.print("File: {s}\n", .{path});
    try writer.print("  type: {s}\n", .{g.label});
    try statAndPrint(writer, path);
    try writer.print("  first move: {s}\n", .{g.first_move});
    if (g.dedicated_skill.len != 0) {
        try writer.print("  dedicated skill: {s}\n", .{g.dedicated_skill});
    } else {
        try writer.print("  dedicated skill: (none)\n", .{});
    }
    try writer.print("  guidance:\n", .{});

    var it = std.mem.splitScalar(u8, g.detail, '\n');
    while (it.next()) |line| {
        try writer.print("    {s}\n", .{line});
    }
    try writer.print("\n", .{});
}

fn printProtocol(writer: anytype) !void {
    const protocol =
        \\Reading Uploaded Files - General Protocol
        \\1. Look at the extension. That is your dispatch key.
        \\2. Stat before you read. Large files need sampling, not slurping.
        \\3. Read just enough to answer the user's question.
        \\4. If a dedicated skill exists, go read it for editing, creating, and advanced operations.
        \\Do not blindly cat binary files. Do not flood your context with rows you will never use.
        \\
    ;
    var it = std.mem.splitScalar(u8, protocol, '\n');
    while (it.next()) |line| {
        try writer.print("{s}\n", .{line});
    }
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const args = try std.process.argsAlloc(allocator);
    defer std.process.argsFree(allocator, args);

    const stdout_file = std.io.getStdOut();
    var buffered = std.io.bufferedWriter(stdout_file.writer());
    const writer = buffered.writer();

    if (args.len < 2) {
        try writer.print("Usage: {s} <uploaded-file-path> [more paths...]\n\n", .{args[0]});
        try printProtocol(writer);
        try buffered.flush();
        return;
    }

    try printProtocol(writer);
    try writer.print("\n", .{});

    var i: usize = 1;
    while (i < args.len) : (i += 1) {
        try processPath(writer, args[i]);
    }

    try buffered.flush();
}
